#!/usr/bin/env bash
# Debian 12/13 x86_64: complete source bundle, compiled on the VPS.
# Includes deployment files and ICANN suffixes; downloads gfwlist and eighteen service lists.
set -Eeuo pipefail
if [[ ${1:-} != --help && ${1:-} != -h && $EUID != 0 ]]; then
    echo 'Run this script with sudo bash /tmp/network-relay-install-from-source.sh.' >&2
    exit 1
fi

bundle_dir=$(mktemp -d "${TMPDIR:-/tmp}/network-relay-installer.XXXXXX")
